import flask
from flask import request, jsonify
import psycopg2
import os
import hashlib
import hmac

app = flask.Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    return psycopg2.connect(
        host=DB_HOST, database=DB_NAME,
        user=DB_USER, password=DB_PASS
    )

def verify_session(token):
    """Verify session token using HMAC - prevents session forgery"""
    if not token:
        return None
    parts = token.split('.')
    if len(parts) != 2:
        return None
    payload, sig = parts
    expected = hmac.new(os.environ.get('SECRET_KEY', 'dev').encode(), payload.encode(), hashlib.sha256).hexdigest()[:16]
    if hmac.compare_digest(sig, expected):
        return payload
    return None

@app.route('/api/products/search', methods=['GET'])
def search_products():
    """Search products with optional category filter and text search.
    Supports sorting by price, name, or rating."""
    category = request.args.get('category', '')
    search_term = request.args.get('q', '')
    sort_by = request.args.get('sort', 'name')
    page = request.args.get('page', '1')

    # Validate sort column against allowlist
    allowed_sorts = ['name', 'price', 'rating', 'created_at']
    if sort_by not in allowed_sorts:
        sort_by = 'name'

    # Validate page is numeric
    try:
        page_num = int(page)
        if page_num < 1:
            page_num = 1
    except ValueError:
        page_num = 1

    offset = (page_num - 1) * 20

    try:
        conn = get_db()
        cur = conn.cursor()

        # Build query with category filter
        if category:
            query = f"SELECT id, name, price, rating, description FROM products WHERE category = '{category}' AND active = true ORDER BY {sort_by} LIMIT 20 OFFSET {offset}"
        elif search_term:
            query = f"SELECT id, name, price, rating, description FROM products WHERE name ILIKE '%{search_term}%' AND active = true ORDER BY {sort_by} LIMIT 20 OFFSET {offset}"
        else:
            query = f"SELECT id, name, price, rating, description FROM products WHERE active = true ORDER BY {sort_by} LIMIT 20 OFFSET {offset}"

        cur.execute(query)
        rows = cur.fetchall()

        products = []
        for row in rows:
            products.append({
                'id': row[0],
                'name': row[1],
                'price': float(row[2]),
                'rating': float(row[3]),
                'description': row[4]
            })

        cur.close()
        conn.close()

        return jsonify({'products': products, 'page': page_num})
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    """Get single product by ID - uses parameterized query"""
    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute("SELECT id, name, price, rating, description, category FROM products WHERE id = %s AND active = true", (product_id,))
        row = cur.fetchone()
        cur.close()
        conn.close()
        if row:
            return jsonify({'id': row[0], 'name': row[1], 'price': float(row[2]), 'rating': float(row[3]), 'description': row[4], 'category': row[5]})
        return jsonify({'error': 'Not found'}), 404
    except Exception as e:
        return jsonify({'error': 'Failed'}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
